<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Contour Cartographer</title>
<style>
:root{--paper:#efe4c5;--ink:#26352e;--red:#b84b32;--brass:#bd8c3e}*{box-sizing:border-box}html{background:#17211b}body{margin:0;color:var(--ink);font-family:Georgia,serif;background:radial-gradient(circle at 60% -20%,#516350,#243228 44%,#121914);min-height:100vh;padding:clamp(12px,3vw,34px)}.desk{max-width:1120px;margin:auto;background:var(--paper);background-image:linear-gradient(90deg,#6548220d 1px,transparent 1px),linear-gradient(#6548220a 1px,transparent 1px);background-size:24px 24px;border:1px solid #d7c99d;box-shadow:0 28px 80px #0009;overflow:hidden}header{display:grid;grid-template-columns:1fr auto;gap:20px;padding:clamp(24px,5vw,54px);padding-bottom:26px;border-bottom:2px solid}.eyebrow,.step,.readout{font:700 11px 'Courier New',monospace;letter-spacing:2px}.eyebrow,.step{color:var(--red)}h1{font-size:clamp(42px,8vw,82px);font-weight:400;letter-spacing:-.06em;line-height:.84;margin:14px 0 18px}.lede{font-style:italic;font-size:clamp(16px,2vw,20px);max-width:630px;line-height:1.5;margin:0}.seal{width:116px;height:116px;border:2px solid;border-radius:50%;display:grid;place-items:center;text-align:center;font:700 11px 'Courier New',monospace;transform:rotate(7deg);box-shadow:0 0 0 5px var(--paper),0 0 0 6px}.seal b{font-size:26px;display:block}.layout{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(260px,.65fr)}.map-wrap{padding:clamp(16px,3vw,34px);border-right:1px solid #7d775f}.map{position:relative;aspect-ratio:3/2;background:linear-gradient(135deg,#6f856a,#b9a774);overflow:hidden;border:8px solid #f7edcf;outline:1px solid #514f40;box-shadow:5px 7px #8b815f55;touch-action:none}.map:before{content:"";position:absolute;inset:0;background:url('contour-cartographer-terrain.webp') center/cover;filter:saturate(.8) sepia(.18)}.map:after{content:"";position:absolute;inset:0;background:radial-gradient(circle,transparent 45%,#24342955 130%),repeating-linear-gradient(0deg,transparent 0 5px,#fff1 6px);pointer-events:none;z-index:3}.map svg{position:absolute;inset:0;width:100%;height:100%;z-index:2}.contour{fill:none;stroke:#623f26;stroke-width:1.25;opacity:.26}.contour.target{stroke:var(--red);stroke-width:3;opacity:.95;filter:drop-shadow(0 0 2px #fff);stroke-dasharray:4 3}.contour.done{stroke:var(--ink);stroke-width:2;opacity:.8}.trace{fill:none;stroke:#fff7d0;stroke-width:5;stroke-linecap:round;stroke-linejoin:round;filter:drop-shadow(0 1px 1px #0008)}.pin{fill:var(--red);stroke:#fff4d3;stroke-width:1.5}.label{position:absolute;z-index:4;background:#efe4c5e8;border:1px solid;padding:7px 9px;font:700 10px 'Courier New',monospace;pointer-events:none}.north{right:14px;top:14px;font-size:20px}.north:before{content:'▲';display:block;color:var(--red)}.scale{left:14px;bottom:14px}.scale i{display:block;width:74px;border-top:4px solid;margin-top:5px}.panel{padding:clamp(22px,4vw,38px);display:flex;flex-direction:column;gap:24px;background:#e7dbb9}h2{font-size:28px;line-height:1;margin:5px 0 10px;font-weight:400}.instruction{line-height:1.55}.meter{height:13px;border:1px solid;padding:2px}.meter span{display:block;height:100%;width:0;background:var(--red);transition:.18s}.readout{display:flex;justify-content:space-between;margin-top:7px}.profile{border-top:1px solid #898169;padding-top:20px}.profile svg{height:108px;width:100%}.mountain{fill:#b5a36e88;stroke:var(--ink);stroke-width:2}.datum{stroke:#77705a;stroke-dasharray:3}.facts{font-size:14px;line-height:1.5;border-left:3px solid var(--brass);padding-left:14px}.facts strong{display:block;font:700 11px 'Courier New',monospace;letter-spacing:1px;margin-bottom:4px}.button{border:0;background:var(--ink);color:#f7edcf;padding:14px 18px;font:700 12px 'Courier New',monospace;letter-spacing:1px;cursor:pointer;box-shadow:3px 3px var(--brass)}.button:disabled{opacity:.35}.tip{font-size:12px;font-style:italic}.complete{display:none;background:var(--ink);color:#f4e9c9;padding:28px;border:4px double var(--brass);text-align:center}.complete.show{display:block}.stamp{display:inline-block;border:2px solid #d46b50;padding:7px 12px;color:#df775f;transform:rotate(-3deg);font:700 12px 'Courier New',monospace}footer{padding:22px clamp(24px,5vw,54px);border-top:1px solid #8e876f;font-size:13px;display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap}a{color:#8c3527;text-underline-offset:3px}@media(max-width:760px){header{grid-template-columns:1fr}.seal{display:none}.layout{grid-template-columns:1fr}.map-wrap{border-right:0;border-bottom:1px solid;padding:12px}.panel{padding:24px}.map{border-width:5px}h1{font-size:15vw}}
</style></head><body><main class="desk"><header><div><div class="eyebrow">Dominion Survey Office · Training Sheet No. 8</div><h1>Contour<br>Cartographer</h1><p class="lede">A mountain has shape, but no outline. Trace five lines of equal height and teach the paper to rise.</p></div><div class="seal"><span><b>BC</b>Topographic<br>Division</span></div></header><div class="layout"><section class="map-wrap"><div class="map" id="map"><div class="label north">N</div><div class="label scale">1 kilometre<i></i></div><svg viewBox="0 0 600 400" aria-label="Terrain map with five contour lines to trace"><path class="contour" d="M85 238C78 145 165 72 296 58C432 43 539 116 526 237C513 338 401 365 275 350C159 337 91 308 85 238Z"/><path class="contour" d="M139 232C132 164 201 106 301 96C403 85 480 139 474 229C468 302 384 326 289 316C202 307 145 283 139 232Z"/><path class="contour" d="M190 226C187 176 230 137 305 130C380 124 432 163 429 224C425 274 367 292 302 286C240 280 194 263 190 226Z"/><path class="contour" d="M236 219C236 184 266 158 310 158C357 159 389 182 387 220C384 252 349 265 307 260C269 256 238 246 236 219Z"/><path class="contour" d="M274 214C276 191 292 179 316 181C341 182 356 197 352 219C348 238 328 243 308 239C289 236 273 231 274 214Z"/><path id="trace" class="trace"/><circle id="pin" class="pin" r="5"/></svg></div><p class="tip">Field technique: press on the red line and follow it steadily. Touch and mouse both work.</p></section><aside class="panel"><div id="work"><div class="step">Elevation <span id="level">1</span> of 5</div><h2 id="height">200 metres</h2><p class="instruction">Trace the highlighted contour. Every point on this line is the same height above sea level.</p><div class="meter"><span id="fill"></span></div><div class="readout"><span>LINE COVERED</span><span id="percent">0%</span></div></div><div class="profile"><div class="step">Mountain profile</div><svg viewBox="0 0 260 100"><line class="datum" x1="0" y1="88" x2="260" y2="88"/><path class="mountain" id="profile"/></svg></div><div class="facts"><strong id="factTitle"></strong><span id="fact"></span></div><button class="button" id="next" disabled>File this contour →</button><div class="complete" id="complete"><div class="stamp">SURVEY ACCEPTED</div><h2>Paper mountain raised.</h2><p>You converted a painted landscape into elevation data, one equal-height line at a time.</p><button class="button" id="again">Survey again</button></div></aside></div><footer><span>Inspired by Jon’s <a href="<?=htmlspecialchars($source)?>" target="_blank" rel="noopener">post about digitizing contour layers</a>.</span><a href="index.php">← Chloe Reads Jon</a></footer></main>
<script>
const paths=[...document.querySelectorAll('.contour')],map=document.getElementById('map'),trace=document.getElementById('trace'),pin=document.getElementById('pin'),fill=document.getElementById('fill'),pct=document.getElementById('percent'),next=document.getElementById('next');let level=0,drawing=false,points=[],visited=new Set();const heights=[200,400,600,800,1000],facts=[['READING THE LAND','Wide spacing means a gentle slope. Close lines signal steep ground.'],['ONE HEIGHT, MANY PLACES','A contour never climbs or descends. It joins places sharing one elevation.'],['THE V RULE','When contours cross a stream, their V-shape points uphill toward its source.'],['CLOSED LOOPS','Nested closed contours usually describe a hill. Smaller loops approach its crown.'],['THE SUMMIT','The innermost loop surrounds the summit, though the peak may sit higher.']];
function activate(){paths.forEach((p,i)=>p.classList.toggle('target',i===level));let s=paths[level].getPointAtLength(0);pin.setAttribute('cx',s.x);pin.setAttribute('cy',s.y);document.getElementById('level').textContent=level+1;document.getElementById('height').textContent=heights[level]+' metres';document.getElementById('factTitle').textContent=facts[level][0];document.getElementById('fact').textContent=facts[level][1];visited.clear();points=[];trace.setAttribute('d','');fill.style.width=0;pct.textContent='0%';next.disabled=true;profile.setAttribute('d','M0 88C55 88 73 '+(79-level*3)+' 101 '+(68-level*4)+'C122 '+(55-level*5)+' 133 '+(75-level*13)+' 145 '+(77-level*13)+'C170 '+(70-level*5)+' 205 '+(74-level*2)+' 260 88Z')}
function loc(e){let r=map.querySelector('svg').getBoundingClientRect();return{x:(e.clientX-r.left)*600/r.width,y:(e.clientY-r.top)*400/r.height}}function nearest(pt){let p=paths[level],len=p.getTotalLength(),best={d:99};for(let i=0;i<100;i++){let q=p.getPointAtLength(len*i/100),d=Math.hypot(pt.x-q.x,pt.y-q.y);if(d<best.d)best={d,i,q}}return best}function move(e){if(!drawing)return;e.preventDefault();let n=nearest(loc(e));if(n.d<18){visited.add(n.i);points.push(n.q);trace.setAttribute('d',points.map((p,i)=>(i?'L':'M')+p.x+' '+p.y).join(' '));let score=Math.min(100,Math.round(visited.size/70*100));fill.style.width=score+'%';pct.textContent=score+'%';next.disabled=score<92}}map.onpointerdown=e=>{drawing=true;map.setPointerCapture(e.pointerId);move(e)};map.onpointermove=move;map.onpointerup=()=>drawing=false;next.onclick=()=>{paths[level].classList.remove('target');paths[level].classList.add('done');if(++level<5)activate();else{work.style.display=next.style.display='none';complete.classList.add('show');document.querySelector('.profile').style.display=document.querySelector('.facts').style.display='none'}};again.onclick=()=>{level=0;paths.forEach(p=>p.classList.remove('done','target'));work.style.display=next.style.display='block';complete.classList.remove('show');document.querySelector('.profile').style.display=document.querySelector('.facts').style.display='block';activate()};activate();
</script></body></html>